-- Catálogo de Springis (17/11/2026): secciones y 49 productos sin precio.
begin;
delete from public.secciones s where s.id in ('ramilletes','arreglos','cajas','centros') and not exists (select 1 from public.productos p where p.categoria = s.id);
insert into public.secciones (id, nombre, emoji, orden) values ('rosas','Rosas','',10), ('girasoles','Girasoles','',20), ('primaverales','Primaverales','',30), ('bolsitas','Bolsitas','',40), ('cajitas','Cajitas y box','',50), ('otras','Otras opciones','',60) on conflict (id) do update set nombre = excluded.nombre, orden = excluded.orden;
